python - <<'PY'
import json,subprocess,collections
j=json.load(open('/tmp/ghostcandidate.json')); d=collections.defaultdict(list)
for x in j['diagrams'][0]['mappings']:d[x['path']].append((x['startLine'],x['endLine']))
for f,rr in d.items():
 lines=open(f).read().splitlines(); print('===',f,len(lines),'ranges',len(rr));
 for a,b in sorted(set(rr)):
  assert a>0 and b<=len(lines) and a<=b,(f,a,b,len(lines))
  # numbered independently for each file (nl -ba)
  out=subprocess.check_output(['nl','-ba',f],text=True).splitlines()
  print(f'{a}-{b}:',out[a-1].strip(),' ... ',out[b-1].strip())
PY

